import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the built-in defaults and return the values.

    Defaults are mode="fast" and level="3". keys[i] is set to values[i]; if a
    key repeats, the last value wins. The result holds the value of "mode",
    then the value of "level", then the values of any other keys in the order
    they first appear in `keys`.

    Raises ValueError if keys and values differ in length.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    merged: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        merged[k] = v
    return list(merged.values())


def test_defaults_when_empty() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level() -> None:
    assert settings(["level"], ["7"]) == ["fast", "7"]


def test_override_both_in_reverse_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_follow_in_given_order() -> None:
    assert settings(["z", "a", "m"], ["1", "2", "3"]) == ["fast", "3", "1", "2", "3"]


def test_extras_mixed_with_overrides() -> None:
    keys = ["x", "level", "y", "mode"]
    values = ["vx", "9", "vy", "turbo"]
    assert settings(keys, values) == ["turbo", "9", "vx", "vy"]


def test_duplicate_key_last_value_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_duplicate_extra_keeps_first_position() -> None:
    keys = ["p", "q", "p"]
    values = ["1", "2", "3"]
    assert settings(keys, values) == ["fast", "3", "3", "2"]


def test_empty_string_value_is_kept() -> None:
    assert settings(["mode", "k"], ["", ""]) == ["", "3", ""]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings([], ["1"])


def test_inputs_not_mutated() -> None:
    keys = ["mode", "k"]
    values = ["slow", "v"]
    settings(keys, values)
    assert keys == ["mode", "k"]
    assert values == ["slow", "v"]
